/* Lot 95: values of the Lot 95 types, lists and transform functions against a syntax (generated by scripts/lot95_propgen.py; expectations from lot95_propmodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;

static int mp(const char *syn, const char *v) {
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(syn, (int)strlen(syn), &g_p);
    if (g_p.syntax == WF_CSSPROP_BAD) return -1;
    return wf_cssprop_match_prop(&g_p, v);
}

static void test_l95_match_0(void) {
    TEST_ASSERT_EQUAL(0, wf_cssprop_match(WF_CSSPROP_IMAGE, "conic-gradient()"));
    TEST_ASSERT_EQUAL(0, wf_cssprop_match(WF_CSSPROP_TLIST, "none"));
    TEST_ASSERT_EQUAL(0, wf_cssprop_match(WF_CSSPROP_IMAGE, "repeating-conic-gradient()"));
    TEST_ASSERT_EQUAL(1, mp("'<image> | <time>'", "calc(+1500ms)"));
    TEST_ASSERT_EQUAL(0, mp("'<transform-list> | stretch'", "left-side"));
    TEST_ASSERT_EQUAL(0, mp("'<transform-list>'", "skewx(1px)"));
    TEST_ASSERT_EQUAL(0, wf_cssprop_match(WF_CSSPROP_TFUNC, "scale()"));
    TEST_ASSERT_EQUAL(1, mp("'<transform-list>'", "skewx( -3.28336turn )"));
    TEST_ASSERT_EQUAL(0, mp("'<resolution> | <string> | <color> | <integer>+ | <resolution> | <transform-list> | <time>+ | small'", "1000s  calc(74ms - +392s)  calc(-500turn * +0)  +12%"));
    TEST_ASSERT_EQUAL(1, mp("'<resolution> | <image>+ | <string> | <custom-ident>'", "radial-gradient(to right, red 10%, blue)  repeating-radial-gradient(red)"));
}

static void test_l95_match_1(void) {
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_TLIST, "skewx( -1.6grad ) perspective(86cm)"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_URL, "url(a.png)"));
    TEST_ASSERT_EQUAL(1, mp("'<image># | <percentage># | <color> | <string>+'", "repeating-conic-gradient(from 90deg, red, blue), radial-gradient(rgb(1, 2, 3), white)"));
    TEST_ASSERT_EQUAL(0, mp("'<string>+ | <url>+ | <resolution> | <transform-list> | <transform-list> | <number> | <transform-list> | left-side'", "x"));
    TEST_ASSERT_EQUAL(0, mp("'<transform-function>+'", "rotate4d(calc(90deg - 90deg)) perspective(calc(5vmax + 500mm - +90vmin))"));
    TEST_ASSERT_EQUAL(1, mp("'<resolution># | <string>#'", "calc(+136.5x / 3 + +35.0dpcm - 85dpcm),252dpcm"));
    TEST_ASSERT_EQUAL(0, mp("'<string> | <string> | <angle>'", "abc'"));
    TEST_ASSERT_EQUAL(1, mp("'<string>'", "\"x\\\"y\""));
    TEST_ASSERT_EQUAL(1, mp("'<resolution>'", "calc(0dppx)"));
    TEST_ASSERT_EQUAL(1, mp("'<string>+'", "\"a'b\" \"a'b\""));
}

static void test_l95_match_2(void) {
    TEST_ASSERT_EQUAL(1, mp("'<image> | <color> | <time># | <length-percentage>'", "repeating-conic-gradient(circle, red, blue)"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_TFUNC, "rotatex(-360.9331grad)"));
    TEST_ASSERT_EQUAL(1, mp("'<transform-function> | <image> | <transform-list> | <string>'", "translatez(calc(12pc - 10em + 12pt))"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_URL, "url(\"a'b.png\")"));
    TEST_ASSERT_EQUAL(1, mp("'<transform-function># | small'", "skewy(calc(+12.2grad - +5turn))"));
    TEST_ASSERT_EQUAL(0, mp("'<image> | stretch+'", "left-side -moz-thing _under left-side"));
    TEST_ASSERT_EQUAL(0, mp("'<image> | <image>'", "url(a b.png)"));
    TEST_ASSERT_EQUAL(0, mp("'<image> | <resolution> | auto | <string> | <angle># | <percentage>+ | <resolution># | <resolution>'", "big"));
    TEST_ASSERT_EQUAL(0, wf_cssprop_match(WF_CSSPROP_TFUNC, "scalez(1px)"));
    TEST_ASSERT_EQUAL(1, mp("'<transform-function> | auto#'", "skewy(-0)"));
}

static void test_l95_match_3(void) {
    TEST_ASSERT_EQUAL(1, mp("'<string> | none | <number> | <length> | <angle> | x+ | <url>+ | <time>+'", "-45.6deg"));
    TEST_ASSERT_EQUAL(0, mp("'<image>#'", "repeating-linear-gradient(red, blue) x , url(a.png) , linear-gradient(red, (blue) , repeating-linear-gradient( )"));
    TEST_ASSERT_EQUAL(0, mp("'<string>'", "abc'"));
    TEST_ASSERT_EQUAL(1, mp("'<image> | <length-percentage>#'", "conic-gradient(red, blue)"));
    TEST_ASSERT_EQUAL(1, mp("'<transform-function>+ | big | auto+ | <angle>'", "auto"));
    TEST_ASSERT_EQUAL(0, wf_cssprop_match(WF_CSSPROP_URL, "url(a"));
    TEST_ASSERT_EQUAL(0, wf_cssprop_match(WF_CSSPROP_RESOLUTION, "1px"));
    TEST_ASSERT_EQUAL(1, mp("'<transform-function> | <url> | small | <length-percentage>+ | big | <string> | <image> | <resolution>'", "url('q\\'r.png')"));
    TEST_ASSERT_EQUAL(0, wf_cssprop_match(WF_CSSPROP_URL, "url(\"a.png\" x)"));
    TEST_ASSERT_EQUAL(1, mp("'<string>#'", "'abc', 'a\\'b', '\\\\'"));
}

